#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> rods(n);
    for (int i = 0; i < n; i++) cin >> rods[i];

    long long S = 0;
    for (long long r : rods) S += r;
    vector<long long> best(S + 1, -1);
    best[0] = 0;
    for (long long r : rods) {
        vector<long long> next = best;
        for (long long d = 0; d <= S; d++) {
            long long h = best[d];
            if (h < 0) continue;
            if (d + r <= S) next[d + r] = max(next[d + r], h + r);
            if (r <= d) next[d - r] = max(next[d - r], h);
            else next[r - d] = max(next[r - d], h - d + r);
        }
        best = next;
    }
    cout << best[0] << "\n";

    return 0;
}

