import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] rods = new long[(int) n];
        for (int i = 0; i < rods.length; i++) rods[i] = Long.parseLong(next());

        int total = 0;
        for (int i = 0; i < n; i++) total += (int) rods[i];
        long[] best = new long[total + 1];
        long[] next = new long[total + 1];
        Arrays.fill(best, -1);
        best[0] = 0;
        for (int k = 0; k < n; k++) {
            int r = (int) rods[k];
            System.arraycopy(best, 0, next, 0, total + 1);
            for (int d = 0; d <= total; d++) {
                long h = best[d];
                if (h < 0) continue;
                if (d + r <= total) next[d + r] = Math.max(next[d + r], h + r);
                if (r <= d) next[d - r] = Math.max(next[d - r], h);
                else next[r - d] = Math.max(next[r - d], h - d + r);
            }
            long[] swap = best;
            best = next;
            next = swap;
        }
        System.out.println(best[0]);
    }
}
